<template>
  <div class="container">
    <h2 class="text-center">弱點分析</h2>
    <button class="btn btn-outline-secondary btn-sm mb-3" type="button" @click="$router.push('/examLobby')">返回大廳</button>
    <!-- 訊息提示框 -->
    <Alert
      :MODE="MSG.MODE"
      :MSGTYPE="MSG.TYPE"
      :TITLE="MSG.TITLE"
      :TEXT="MSG.TEXT"
      @alert-check="(isClick, OKorCancel) => (alertCheck = { isClick, OKorCancel })"
    />
    <div class="row">
      <div class="col-6 text-center">
        準則-預估分數 <span class="badge bg-danger"> {{ predictedScore.score_std }} </span> 分
      </div>
      <div class="col-6 text-center">
        學科-預估分數 <span class="badge bg-danger"> {{ predictedScore.score_sub }} </span> 分
      </div>
      <div class="col-12 h3 mt-4">查詢各科狀況</div>
      <div class="col-12">
        <div class="form-check form-check-inline">
          <input class="form-check-input" type="radio" name="examTypeRadioOptions" id="examTypeRadio1" value="準則" checked v-model="examType" />
          <label class="form-check-label" for="examTypeRadio1">準則</label>
        </div>
        <div class="form-check form-check-inline">
          <input class="form-check-input" type="radio" name="examTypeRadioOptions" id="examTypeRadio2" value="學科" v-model="examType" />
          <label class="form-check-label" for="examTypeRadio2">學科</label>
        </div>
      </div>
      <div class="col-12">
        <select class="form-select form-select-lg mb-2" aria-label=".form-select-lg example" v-model="selected">
          <option selected>請選擇科目</option>
          <option v-for="item in learningRecordDeal" :value="item.QGID">{{ item.subject }}</option>
        </select>
      </div>
      <div class="col-12 d-grid gap-2 my-2">
        <button class="btn btn-primary btn-lg" type="button" @click="queryInfo(selected)">查詢</button>
      </div>
    </div>
    <p v-if="Object.keys(learningRecord).length === 0" class="text-danger fw-bold fs-5 text-center mt-5">尚未查詢紀錄。</p>
    <div v-else class="row">
      <div class="col-12 mt-3">
        <div id="chartPie" class="pie-wrap"></div>
      </div>
      <div class="col-12 text-center">
        <button class="btn btn-outline-danger btn-sm my-3" type="button" disabled>刪除此學習紀錄(開發中)</button>
      </div>
      <div class="col-12">
        <label for="fontSize" class="form-label">文字大小：{{ fontSize - 15 }}級</label>
        <input type="range" class="form-range" min="16" max="40" step="1" id="fontSize" v-model="fontSize" />
      </div>
      <div class="col-12" :style="{ fontSize: fontSize + 'px' }">
        <table v-if="learningRecord.questData.TFQ.length !== 0">
          <tr>
            <td colspan="3" class="h2 text-center">是非</td>
          </tr>
          <tr>
            <th class="h4">#</th>
            <th class="h4">答案</th>
            <th class="h4">題目</th>
          </tr>
          <tr
            v-for="(item, index) in learningRecord.questData.TFQ"
            :style="
              item.familiarity <= 0
                ? 'background-color: #EE6666'
                : item.familiarity >= 0.1 && item.familiarity <= 2.9
                ? 'background-color: #FAC858'
                : item.familiarity >= 3 && item.familiarity <= 4
                ? 'background-color: #91CC75'
                : 'background-color: #5470C6'
            "
          >
            <td>{{ index + 1 }}</td>
            <td class="text-center">{{ item.correct }}</td>
            <td>{{ item.content }}</td>
          </tr>
        </table>
        <table v-if="learningRecord.questData.SCQ.length !== 0">
          <tr>
            <td colspan="3" class="h2 text-center">單選</td>
          </tr>
          <tr>
            <th class="h4">#</th>
            <th class="h4">答案</th>
            <th class="h4">題目</th>
          </tr>
          <tr
            v-for="(item, index) in learningRecord.questData.SCQ"
            :style="
              item.familiarity <= 0
                ? 'background-color: #EE6666'
                : item.familiarity >= 0.1 && item.familiarity <= 2.9
                ? 'background-color: #FAC858'
                : item.familiarity >= 3 && item.familiarity <= 4
                ? 'background-color: #91CC75'
                : 'background-color: #5470C6'
            "
          >
            <td>{{ index + 1 }}</td>
            <td class="text-center">{{ item.correctIndex }}</td>
            <td>
              <p class="fw-bold">{{ item.content }}</p>
              <p v-for="(option, i) in item.options" class="d-inline mx-2">{{ i + 1 }}.{{ item.options[i] }}</p>
            </td>
          </tr>
        </table>
        <table v-if="learningRecord.questData.MCQ.length !== 0">
          <tr>
            <td colspan="3" class="h2 text-center">多選</td>
          </tr>
          <tr>
            <th class="h4">#</th>
            <th class="h4">答案</th>
            <th class="h4">題目</th>
          </tr>
          <tr
            v-for="(item, index) in learningRecord.questData.MCQ"
            :style="
              item.familiarity <= 0
                ? 'background-color: #EE6666'
                : item.familiarity >= 0.1 && item.familiarity <= 2.9
                ? 'background-color: #FAC858'
                : item.familiarity >= 3 && item.familiarity <= 4
                ? 'background-color: #91CC75'
                : 'background-color: #5470C6'
            "
          >
            <td>{{ index + 1 }}</td>
            <td>{{ item.correctIndex.join() }}</td>
            <td>
              <p class="fw-bold">{{ item.content }}</p>
              <p v-for="(option, i) in item.options" class="d-inline mx-2">{{ i + 1 }}.{{ item.options[i] }}</p>
            </td>
          </tr>
        </table>
      </div>
    </div>
  </div>
</template>

<script>
import Alert from "@/components/Alert.vue";
import * as echarts from "echarts";
require("echarts/theme/macarons"); //引入主题

export default {
  name: "WeakAnalysis",
  components: {
    Alert,
  },
  data() {
    return {
      // 訊息提示框資料容器
      MSG: {
        MODE: "",
        TYPE: "",
        TITLE: "",
        TEXT: [],
      },
      // 訊息確認[開關]
      alertCheck: false,
      // 訊息功能碼
      funcNum: 0,
      predictedScore: {
        score_std: 0,
        score_sub: 0,
      },
      learningRecordData: [],
      examType: "準則",
      learningRecordDeal: [],
      selected: "請選擇科目",
      chartPie: null,
      fontSize: 16, // 文字大小
      learningRecord: {},
    };
  },
  methods: {
    queryInfo() {
      if (this.selected === "請選擇科目") {
        // 訊息提示框
        this.alertVisible = true;
        this.MSG.MODE = "OKOnly"; // 形式為：OKOnly、OKCancel
        this.funcNum = -1;
        this.MSG.TYPE = "warning"; // primary成功, warning警告, danger錯誤
        this.MSG.TITLE = "系統警告"; // 系統提示，系統警告，系統錯誤
        this.MSG.TEXT = ["請選擇科目。"]; // 內容
        return;
      }
      // 利用QGID找learningRecordData符合的資料並存在learningRecord中
      let learningRecord = this.learningRecordDeal.find((item) => item.QGID === this.selected);
      // 統計熟悉度
      let count = {
        notGood: 0,
        good: 0,
        well: 0,
        veryGood: 0,
      };
      for (let key in learningRecord.familiarity) {
        let data = learningRecord.familiarity[key];
        data.forEach((item) => {
          if (item <= 0) {
            count.notGood++;
          } else if (item >= 0.1 && item <= 2.9) {
            count.good++;
          } else if (item >= 3 && item <= 4) {
            count.well++;
          } else if (item >= 4.1 && item <= 5) {
            count.veryGood++;
          }
        });
      }
      learningRecord.familiarityData = [
        { value: count.veryGood, name: "精通" },
        { value: count.well, name: "已熟悉" },
        { value: count.good, name: "微熟悉" },
        { value: count.notGood, name: "不熟悉" },
      ];
      // 把熟悉度資料放到questData中
      learningRecord.questData.TFQ.forEach((item, index) => {
        item.familiarity = learningRecord.familiarity.TFQ[index];
      });
      learningRecord.questData.SCQ.forEach((item, index) => {
        item.familiarity = learningRecord.familiarity.SCQ[index];
      });
      learningRecord.questData.MCQ.forEach((item, index) => {
        item.familiarity = learningRecord.familiarity.MCQ[index];
      });
      // 處理correctIndex
      learningRecord.questData.SCQ.forEach((item) => {
        item.correctIndex = item.options.indexOf(item.correct) + 1;
      });
      learningRecord.questData.MCQ.forEach((item) => {
        item.correctIndex = [];
        item.correct.forEach((correct) => {
          item.correctIndex.push(item.options.indexOf(correct) + 1);
        });
        item.correctIndex.sort((a, b) => a - b);
      });
      // 資料綁定
      this.learningRecord = learningRecord;
      // 初始化圖表
      this.$nextTick(() => {
        let mytextStyle = {
          color: "#333",
          fontSize: 18,
        };
        let mylabel = {
          show: true,
          position: "right",
          offset: [30, 40],
          formatter: "{b} : {c} ({d}%)",
          textStyle: mytextStyle,
        };
        this.chartPie = echarts.init(document.getElementById("chartPie"), "macarons");
        this.chartPie.setOption({
          title: {
            text: this.learningRecord.subject,
            x: "center",
          },
          tooltip: {
            trigger: "item",
            formatter: "{a} <br/>{b} : {c} ({d}%)",
          },
          legend: {
            data: ["不熟悉", "微熟悉", "已熟悉", "精通"],
            left: "center",
            top: "bottom",
            orient: "horizontal",
          },
          series: [
            {
              name: "弱點分析",
              type: "pie",
              radius: ["50%", "70%"],
              center: ["50%", "50%"],
              data: this.learningRecord.familiarityData,
              animationEasing: "cubicInOut",
              animationDuration: 2000,
            },
          ],
        });
      });
    },
    hideAlert() {
      this.$store.commit("SET_ALERT_VISIBLE", false);
      this.alertVisible = false;
    },
  },
  created() {
    // 取得預估分數
    this.$http
      .get("api/users/predictedScore")
      .then((res) => {
        if (res.data.code === 200) {
          this.predictedScore = res.data.data;
        } else {
          this.alertVisible = true;
          this.MSG.MODE = "OKOnly";
          this.funcNum = -1;
          this.MSG.TYPE = "danger";
          this.MSG.TITLE = "系統錯誤";
          this.MSG.TEXT = [];
          this.MSG.TEXT = this.MSG.TEXT.concat(res.data.msg);
          if (res.data.sys !== "") this.MSG.TEXT.push(res.data.sys);
        }
      })
      .catch((err) => {
        this.alertVisible = true;
        this.MSG.MODE = "OKOnly";
        this.funcNum = -1;
        this.MSG.TYPE = "danger";
        this.MSG.TITLE = "系統錯誤";
        this.MSG.TEXT = [];
        this.MSG.TEXT.push(err);
      });

    // 取得用戶學習紀錄
    this.$http
      .get("api/users/learningRecord")
      .then((res) => {
        if (res.data.code === 200) {
          // 判斷是否為空值
          if (Object.keys(res.data.data).length === 0) {
            this.learningRecordData = [];
          } else {
            this.learningRecordData = res.data.data;
            // 初始化列表
            this.learningRecordDeal = this.learningRecordData.filter((item) => item.type === "準則");
          }
        } else {
          this.alertVisible = true;
          this.MSG.MODE = "OKOnly";
          this.funcNum = -1;
          this.MSG.TYPE = "danger";
          this.MSG.TITLE = "系統錯誤";
          this.MSG.TEXT = [];
          this.MSG.TEXT = this.MSG.TEXT.concat(res.data.msg);
          if (res.data.sys !== "") this.MSG.TEXT.push(res.data.sys);
        }
      })
      .catch((err) => {
        this.alertVisible = true;
        this.MSG.MODE = "OKOnly";
        this.funcNum = -1;
        this.MSG.TYPE = "danger";
        this.MSG.TITLE = "系統錯誤";
        this.MSG.TEXT = [];
        this.MSG.TEXT.push(err);
      });
  },
  mounted() {},
  computed: {
    // alert開關連動狀態功能
    alertVisible: {
      get() {
        return this.$store.state.alertVisible;
      },
      set(value) {
        this.$store.commit("SET_ALERT_VISIBLE", value);
      },
    },
  },
  watch: {
    examType(newVal) {
      if (newVal === "準則") {
        this.learningRecordDeal = this.learningRecordData.filter((item) => item.type === "準則");
      } else if (newVal === "學科") {
        this.learningRecordDeal = this.learningRecordData.filter((item) => item.type === "學科");
      }
    },
    alertCheck: function (val) {
      if (val.isClick) {
        if (val.OKorCancel === "OK") {
          if (this.funcNum === 0) {
            return;
          } else if (this.funcNum === -1) {
            this.hideAlert();
          } else if (this.funcNum === -2) {
            this.hideAlert();
            this.$router.go(-1);
          }
        } else if (val.OKorCancel === "Cancel") {
          this.hideAlert();
        }
      }
    },
  },
};
</script>

<style lang="scss">
.pie-wrap {
  width: 100%;
  height: 400px;
}
p {
  margin: 0;
}
table {
  border: 5px double black;
  margin: auto;
  width: 100%;
}
td {
  border: 1px solid black;
}
</style>
